/** Damage to an item this enchanted is only half reimbursed. */
const HALF_REIMBURSEMENT_LEVEL = 8;
const HALF_REIMBURSEMENT_RATE = 0.5;
const FULL_REIMBURSEMENT_RATE = 1;

/** How much of a damage the policy reimburses, before the deductible. */
const reimbursementRate = (item: Item): number =>
  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL
    ? HALF_REIMBURSEMENT_RATE
    : FULL_REIMBURSEMENT_RATE;

/**
 * The insured item a damage entry refers to. The spec calls for an error when a
 * claim names an item the policy does not cover (not yet tested); until then an
 * unmatched entry rates as an unenchanted item of its own type.
 */
const damagedItem = (items: Item[], damage: Damage): Item =>
  items.find((item) => item.type === damage.itemType) ?? { type: damage.itemType };

/** Each damaged item carries its own deductible, and never pays out negative. */
const reimbursementAfterDeductible = (damage: Damage, item: Item): number =>
  Math.max(damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE, 0);

const totalReimbursement = (damages: Damage[], items: Item[]): number =>
  damages.reduce(
    (total, damage) => total + reimbursementAfterDeductible(damage, damagedItem(items, damage)),
    0,
  );
